import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

bn_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor bn2d_forward(torch::Tensor x,
                           c10::optional<torch::Tensor> weight,
                           c10::optional<torch::Tensor> bias,
                           c10::optional<torch::Tensor> running_mean,
                           c10::optional<torch::Tensor> running_var,
                           bool training,
                           double momentum,
                           double eps,
                           bool affine,
                           bool track_running_stats);
"""

bn_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
__global__ void bn2d_stats_kernel(const float* __restrict__ X,
                                  double* __restrict__ acc_sum,
                                  double* __restrict__ acc_sumsq,
                                  int N, int C, int HW, int splits)
{
  const int c = blockIdx.y;
  const int part = blockIdx.x;
  const int tid = threadIdx.x;
  double sum = 0.0;
  double sumsq = 0.0;
  if ((HW & 3) == 0) {
    const int HW4 = HW >> 2;
    const int64_t total4 = (int64_t)N * HW4;
    const int64_t chunk4 = (total4 + splits - 1) / splits;
    const int64_t begin4 = (int64_t)part * chunk4;
    const int64_t end4 = min(total4, begin4 + chunk4);
    for (int64_t idx = begin4 + tid; idx < end4; idx += blockDim.x) {
      const int n = (int)(idx / HW4);
      const int p4 = (int)(idx - (int64_t)n * HW4);
      const float4 v = __ldg(reinterpret_cast<const float4*>(X + ((int64_t)n * C + c) * HW) + p4);
      const double d0 = (double)v.x;
      const double d1 = (double)v.y;
      const double d2 = (double)v.z;
      const double d3 = (double)v.w;
      sum += ((d0 + d1) + (d2 + d3));
      sumsq += ((d0 * d0 + d1 * d1) + (d2 * d2 + d3 * d3));
    }
  } else {
    const int64_t total = (int64_t)N * HW;
    const int64_t chunk = (total + splits - 1) / splits;
    const int64_t begin = (int64_t)part * chunk;
    const int64_t end = min(total, begin + chunk);
    for (int64_t idx = begin + tid; idx < end; idx += blockDim.x) {
      const int n = (int)(idx / HW);
      const int p = (int)(idx - (int64_t)n * HW);
      const double v = (double)X[((int64_t)n * C + c) * HW + p];
      sum += v;
      sumsq += v * v;
    }
  }
  __shared__ double s_sum[256];
  __shared__ double s_sumsq[256];
  s_sum[tid] = sum;
  s_sumsq[tid] = sumsq;
  __syncthreads();
  for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
    if (tid < stride) {
      s_sum[tid] += s_sum[tid + stride];
      s_sumsq[tid] += s_sumsq[tid + stride];
    }
    __syncthreads();
  }
  if (tid == 0) {
    atomicAdd(acc_sum + c, s_sum[0]);
    atomicAdd(acc_sumsq + c, s_sumsq[0]);
  }
}
__global__ void bn2d_finalize_kernel(double* __restrict__ acc_sum,
                                     double* __restrict__ acc_sumsq,
                                     const float* __restrict__ G,
                                     const float* __restrict__ B,
                                     float* __restrict__ RM,
                                     float* __restrict__ RV,
                                     float* __restrict__ scale,
                                     float* __restrict__ shift,
                                     int N, int C, int HW,
                                     float eps, float momentum,
                                     int affine, int track_running_stats)
{
  const int c = blockIdx.x * blockDim.x + threadIdx.x;
  if (c >= C) return;
  const double count = (double)N * (double)HW;
  const double mean = acc_sum[c] / count;
  double var = acc_sumsq[c] / count - mean * mean;
  if (var < 0.0) var = 0.0;
  const float mean_f = (float)mean;
  const float invstd = 1.0f / sqrtf((float)var + eps);
  const float g = affine ? (float)G[c] : 1.0f;
  const float b = affine ? (float)B[c] : 0.0f;
  scale[c] = g * invstd;
  shift[c] = b - mean_f * scale[c];
  if (track_running_stats) {
    const float old_m = (float)RM[c];
    RM[c] = (float)((1.0f - momentum) * old_m + momentum * mean_f);
    double unbiased = var;
    if (count > 1.0) {
      unbiased = var * (count / (count - 1.0));
    }
    const float old_v = (float)RV[c];
    RV[c] = (float)((1.0f - momentum) * old_v + momentum * (float)unbiased);
  }
}
__global__ void bn2d_norm_kernel(const float* __restrict__ X,
                                 const float* __restrict__ scale,
                                 const float* __restrict__ shift,
                                 float* __restrict__ Y,
                                 int N, int C, int HW)
{
  const int tid = threadIdx.x;
  const int c = blockIdx.y;
  const int n = blockIdx.z;
  const int64_t off = ((int64_t)n * C + c) * HW;
  const float sc = scale[c];
  const float sh = shift[c];
  const int stride = gridDim.x * blockDim.x;
  if ((HW & 3) == 0) {
    const int HW4 = HW >> 2;
    const float4* __restrict__ X4 = reinterpret_cast<const float4*>(X + off);
    float4* __restrict__ Y4 = reinterpret_cast<float4*>(Y + off);
    for (int p = blockIdx.x * blockDim.x + tid; p < HW4; p += stride) {
      float4 v = __ldg(X4 + p);
      v.x = v.x * sc + sh;
      v.y = v.y * sc + sh;
      v.z = v.z * sc + sh;
      v.w = v.w * sc + sh;
      Y4[p] = v;
    }
    return;
  }
  Tensor mX = make_tensor(make_gmem_ptr(X + off), make_shape(HW), make_stride(Int<1>{}));
  Tensor mY = make_tensor(make_gmem_ptr(Y + off), make_shape(HW), make_stride(Int<1>{}));
  for (int p = blockIdx.x * blockDim.x + tid; p < HW; p += stride) {
    mY(p) = (float)((float)mX(p) * sc + sh);
  }
}
template <typename T>
__global__ void bn2d_infer_kernel(const T* __restrict__ X,
                                  const T* __restrict__ G,
                                  const T* __restrict__ B,
                                  T* __restrict__ Y,
                                  const T* __restrict__ RM,
                                  const T* __restrict__ RV,
                                  int N, int C, int HW,
                                  float eps, int affine)
{
  const int tid = threadIdx.x;
  const int c = blockIdx.y;
  const int n = blockIdx.z;
  const int64_t off = ((int64_t)n * C + c) * HW;
  const float mean = (float)RM[c];
  const float var = (float)RV[c];
  const float invstd = 1.0f / sqrtf(var + eps);
  const float g = affine ? (float)G[c] : 1.0f;
  const float b = affine ? (float)B[c] : 0.0f;
  const float scale = g * invstd;
  const float shift = b - mean * scale;
  const int stride = gridDim.x * blockDim.x;
  if ((HW & 3) == 0) {
    const int HW4 = HW >> 2;
    const float4* __restrict__ X4 = reinterpret_cast<const float4*>(X + off);
    float4* __restrict__ Y4 = reinterpret_cast<float4*>(Y + off);
    for (int p = blockIdx.x * blockDim.x + tid; p < HW4; p += stride) {
      float4 v = __ldg(X4 + p);
      v.x = v.x * scale + shift;
      v.y = v.y * scale + shift;
      v.z = v.z * scale + shift;
      v.w = v.w * scale + shift;
      Y4[p] = v;
    }
    return;
  }
  Tensor mX = make_tensor(make_gmem_ptr(X + off), make_shape(HW), make_stride(Int<1>{}));
  Tensor mY = make_tensor(make_gmem_ptr(Y + off), make_shape(HW), make_stride(Int<1>{}));
  for (int p = blockIdx.x * blockDim.x + tid; p < HW; p += stride) {
    mY(p) = (T)((float)mX(p) * scale + shift);
  }
}
torch::Tensor bn2d_forward(torch::Tensor x,
                           c10::optional<torch::Tensor> weight,
                           c10::optional<torch::Tensor> bias,
                           c10::optional<torch::Tensor> running_mean,
                           c10::optional<torch::Tensor> running_var,
                           bool training,
                           double momentum,
                           double eps,
                           bool affine,
                           bool track_running_stats)
{
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(x.dim() == 4, "x must be NCHW");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  auto x_c = x.contiguous();
  const int64_t N = x_c.size(0);
  const int64_t C = x_c.size(1);
  const int64_t H = x_c.size(2);
  const int64_t W = x_c.size(3);
  const int64_t HW = H * W;
  TORCH_CHECK(HW > 0, "empty spatial dims");
  torch::Tensor w_c, b_c, rm_c, rv_c;
  const float* w_ptr = nullptr;
  const float* b_ptr = nullptr;
  float* rm_ptr = nullptr;
  float* rv_ptr = nullptr;
  if (affine) {
    TORCH_CHECK(weight.has_value() && bias.has_value(), "affine BatchNorm needs weight and bias");
    w_c = weight.value().contiguous();
    b_c = bias.value().contiguous();
    TORCH_CHECK(w_c.numel() == C && b_c.numel() == C, "bad affine parameter shapes");
    TORCH_CHECK(w_c.is_cuda() && b_c.is_cuda(), "affine parameters must be CUDA");
    TORCH_CHECK(w_c.scalar_type() == at::kFloat && b_c.scalar_type() == at::kFloat,
                "affine parameters must be float32");
    w_ptr = w_c.data_ptr<float>();
    b_ptr = b_c.data_ptr<float>();
  }
  if (track_running_stats) {
    TORCH_CHECK(running_mean.has_value() && running_var.has_value(),
                "tracked BatchNorm needs running_mean and running_var");
    rm_c = running_mean.value().contiguous();
    rv_c = running_var.value().contiguous();
    TORCH_CHECK(rm_c.numel() == C && rv_c.numel() == C, "bad running stat shapes");
    TORCH_CHECK(rm_c.is_cuda() && rv_c.is_cuda(), "running stats must be CUDA");
    TORCH_CHECK(rm_c.scalar_type() == at::kFloat && rv_c.scalar_type() == at::kFloat,
                "running stats must be float32");
    rm_ptr = rm_c.data_ptr<float>();
    rv_ptr = rv_c.data_ptr<float>();
  } else {
    TORCH_CHECK(!training, "track_running_stats=False is only supported for inference in this kernel");
    TORCH_CHECK(running_mean.has_value() && running_var.has_value(),
                "inference requires running statistics");
    rm_c = running_mean.value().contiguous();
    rv_c = running_var.value().contiguous();
    rm_ptr = rm_c.data_ptr<float>();
    rv_ptr = rv_c.data_ptr<float>();
  }
  auto y = torch::empty_like(x_c);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  dim3 block(256);
  if (training) {
    TORCH_CHECK(track_running_stats, "training requires track_running_stats=True");
    auto ws = torch::empty({(int64_t)24 * C}, x_c.options().dtype(at::kByte));
    char* ws_ptr = (char*)ws.data_ptr();
    double* acc_sum = reinterpret_cast<double*>(ws_ptr);
    double* acc_sumsq = reinterpret_cast<double*>(ws_ptr + (int64_t)8 * C);
    float* scale = reinterpret_cast<float*>(ws_ptr + (int64_t)16 * C);
    float* shift = reinterpret_cast<float*>(ws_ptr + (int64_t)20 * C);
    cudaMemsetAsync(acc_sum, 0, (size_t)((int64_t)16 * C), stream);
    int splits = (int)((N * HW + 524287) / 524288);
    if (splits < 8) splits = 8;
    if (splits > 32) splits = 32;
    dim3 sgrid((unsigned)splits, (unsigned)C);
    bn2d_stats_kernel<<<sgrid, block, 0, stream>>>(
        x_c.data_ptr<float>(), acc_sum, acc_sumsq, (int)N, (int)C, (int)HW, splits);
    const int fthreads = 128;
    const int fblocks = (int)((C + fthreads - 1) / fthreads);
    bn2d_finalize_kernel<<<fblocks, fthreads, 0, stream>>>(
        acc_sum, acc_sumsq, w_ptr, b_ptr, rm_ptr, rv_ptr, scale, shift,
        (int)N, (int)C, (int)HW, (float)eps, (float)momentum, affine ? 1 : 0, 1);
    int gx = (int)((HW + block.x - 1) / block.x);
    if (gx > 128) gx = 128;
    if (gx < 1) gx = 1;
    dim3 ngrid((unsigned)gx, (unsigned)C, (unsigned)N);
    bn2d_norm_kernel<<<ngrid, block, 0, stream>>>(
        x_c.data_ptr<float>(), scale, shift, y.data_ptr<float>(), (int)N, (int)C, (int)HW);
  } else {
    int gx = (int)((HW + block.x - 1) / block.x);
    if (gx > 128) gx = 128;
    if (gx < 1) gx = 1;
    dim3 grid((unsigned)gx, (unsigned)C, (unsigned)N);
    bn2d_infer_kernel<float><<<grid, block, 0, stream>>>(
        x_c.data_ptr<float>(), w_ptr, b_ptr, y.data_ptr<float>(),
        rm_ptr, rv_ptr, (int)N, (int)C, (int)HW, (float)eps, affine ? 1 : 0);
  }
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "bn2d_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

bn_ext = load_inline(
    name="cute_bn2d_ext",
    cpp_sources=bn_cpp_decl,
    cuda_sources=bn_cuda_src,
    functions=["bn2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    BatchNorm2d-compatible module whose forward computation is performed by a
    custom CuTe/CUDA kernel. Keeps the same `bn.*` state_dict layout as Model.
    """
    def __init__(self, num_features: int):
        super().__init__()
        self.bn = nn.BatchNorm2d(num_features=num_features)
        self._ext = bn_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.bn2d_forward(
            x,
            self.bn.weight,
            self.bn.bias,
            self.bn.running_mean,
            self.bn.running_var,
            bool(self.training),
            float(self.bn.momentum),
            float(self.bn.eps),
            bool(self.bn.affine),
            bool(self.bn.track_running_stats),
        )

